-- The previous migration (20261022090637_add_chat_weak_signal) was
-- generated by `prisma migrate dev` diffing the schema and included an
-- unwanted `DROP INDEX "document_chunks_embedding_hnsw"` — confirmed to have
-- actually dropped it live. This happens because the index lives on
-- document_chunks.embedding, an Unsupported("vector(1536)") column that
-- schema.prisma cannot declare an index for; migrate dev has no way to know
-- the index is intentional and will keep proposing to drop it on every
-- future schema change too. See the loud warning in CLAUDE.md: from here on,
-- always run `prisma migrate dev --create-only`, delete any
-- "DROP INDEX ...hnsw..." line from the generated file by hand, and only
-- then apply it.
--
-- This migration is left in history (rather than rewriting the applied
-- migration above, which would break its stored checksum) specifically so a
-- fresh `prisma migrate deploy` on a brand-new environment ends up with the
-- index present, matching the live database.
CREATE INDEX CONCURRENTLY IF NOT EXISTS document_chunks_embedding_hnsw
  ON document_chunks USING hnsw (embedding vector_cosine_ops);
